function() {
    // Deployment-specific configuration.
    // Each entry excludes the domain itself and all its subdomains.
    function parseDomains(value) {
        if (typeof value !== "string" || !value) {
            return [];
        }

        return value.split(",")
            .map(function(domain) {
                return domain.trim().toLowerCase().replace(/\.$/, "");
            })
            .filter(function(domain) {
                return domain.length > 0;
            });
    }

    var excludedDomains = []
        .concat(parseDomains({{config.entrance.internalDomains}}))
        .concat(parseDomains({{config.entrance.sharedExcludedDomains}}))
        .concat(parseDomains({{config.entrance.extraExcludedDomains}}));

    // Safely obtain the navigation type.
    var navigation;

    try {
        if (
            !window.performance ||
            typeof window.performance.getEntriesByType !== "function"
        ) {
            return undefined;
        }

        navigation = window.performance.getEntriesByType("navigation");
    } catch (error) {
        return undefined;
    }

    if (
        !navigation ||
        !navigation.length ||
        !navigation[0] ||
        navigation[0].type !== "navigate"
    ) {
        return undefined;
    }

    var referrer = {{Referrer}};

    // A missing referrer remains eligible as a direct entrance.
    if (referrer === undefined || referrer === null) {
        return true;
    }

    if (typeof referrer !== "string") {
        return undefined;
    }

    referrer = referrer.trim();

    if (!referrer) {
        return true;
    }

    // Parse the original referrer, not the cleaned reporting value.
    var hostname;

    try {
        var url = new URL(referrer);

        if (
            (url.protocol !== "https:" && url.protocol !== "http:") ||
            !url.hostname
        ) {
            return undefined;
        }

        // Normalize case and an optional trailing DNS dot.
        hostname = url.hostname.toLowerCase().replace(/\.$/, "");
    } catch (error) {
        return undefined;
    }

    // Match an exact hostname or a subdomain separated by a dot.
    for (var i = 0; i < excludedDomains.length; i++) {
        var domain = excludedDomains[i];
        var suffix = "." + domain;

        if (
            hostname === domain ||
            hostname.slice(-suffix.length) === suffix
        ) {
            return undefined;
        }
    }

    return true;
}

function () {
    var ua = navigator.userAgent || '';
    var uaData = navigator.userAgentData;

    // Explicit tablet identifiers, including iPadOS
    if (
        /iPad|Tablet|Kindle|Silk/i.test(ua) ||
        (/Macintosh/i.test(ua) && navigator.maxTouchPoints > 1)
    ) {
        return 'tablet';
    }

    // Structured Android detection when supported
    if (uaData && uaData.platform === 'Android') {
        return uaData.mobile === true ? 'mobile' : 'tablet';
    }

    // Other devices explicitly identified as mobile
    if (uaData && uaData.mobile === true) {
        return 'mobile';
    }

    // Fallback: traditional User-Agent detection
    if (/Mobi|iPhone|iPod|Windows Phone/i.test(ua)) {
        return 'mobile';
    }

    // Android without a mobile identifier
    if (/Android/i.test(ua)) {
        return 'tablet';
    }

    // Desktop identification using structured browser data
    if (uaData && /^(Windows|macOS|Linux|Chrome OS)$/i.test(uaData.platform)) {
        return 'desktop';
    }

    // Desktop fallback using User-Agent identifiers
    if (/Windows NT|Macintosh|CrOS|X11|Linux (x86_64|i686|i386)/i.test(ua)) {
        return 'desktop';
    }

    // No recognized device category
    return 'unknown';
}

function() {
    var referrer = {{Referrer}};

    if (typeof referrer !== "string" || !referrer.trim()) {
        return "(direct)";
    }

    var hostname;

    try {
        var url = new URL(referrer);

        if (url.protocol !== "https:" && url.protocol !== "http:") {
            return "not_available_GTM";
        }

        hostname = url.hostname.toLowerCase().replace(/\.$/, '');

        if (!hostname) {
            return "not_available_GTM";
        }
    } catch (e) {
        return "not_available_GTM";
    }

    function matchesDomain(domain) {
        return hostname === domain ||
            hostname.slice(-(domain.length + 1)) === "." + domain;
    }

    // Starter rules: adapt to your existing classifications.
    var rules = [
        { domain: "google.com", source: "google" },
        { domain: "google.cz", source: "google" },
        { domain: "google.sk", source: "google" },
        { domain: "google.de", source: "google" },
        { domain: "google.se", source: "google" },
        { domain: "bing.com", source: "bing" },
        { domain: "search.seznam.cz", source: "seznam" },
        { domain: "search.yahoo.com", source: "yahoo" },
        { domain: "duckduckgo.com", source: "duckduckgo" },

        { domain: "facebook.com", source: "facebook" },
        { domain: "instagram.com", source: "instagram" },
        { domain: "linkedin.com", source: "linkedin" },
        { domain: "twitter.com", source: "twitter" },
        { domain: "x.com", source: "twitter" },
        { domain: "t.co", source: "twitter" }
    ];

    for (var i = 0; i < rules.length; i++) {
        if (matchesDomain(rules[i].domain)) {
            return rules[i].source;
        }
    }

    return hostname;
}

function () {
    var source = {{URL.query.utm_source}};

    if (typeof source === 'string' && source.trim() && source !== 'not_available_GTM') {
        return (source.trim());
    }

    if ({{URL.query.gclid}}) {
        return ('google');
    }

    return ({{lookup.source}});
}

function() {

  var ts = Math.round(+new Date() / 1000.0);
  var rand;

  try{  
    var uu32 = new Uint32Array(1);
    rand = crypto.getRandomValues(uu32)[0];
  } catch(e) {
    rand = Math.round(Math.random() * 2147483647);
  }

  return [rand, ts].join('.');

}

function() {
    var referrer = {{Referrer}};

    if (typeof referrer !== "string" || !referrer.trim()) {
        return "(none)";
    }

    var hostname;

    try {
        var url = new URL(referrer);

        if (url.protocol !== "https:" && url.protocol !== "http:") {
            return "not_available_GTM";
        }

        hostname = url.hostname.toLowerCase().replace(/\.$/, '');

        if (!hostname) {
            return "not_available_GTM";
        }
    } catch (e) {
        return "not_available_GTM";
    }

    function matchesDomain(domain) {
        return hostname === domain ||
            hostname.slice(-(domain.length + 1)) === "." + domain;
    }

    // Keep these domains consistent with js.lookup.source.
    var rules = [
        { domain: "google.com", medium: "organic" },
        { domain: "google.cz", medium: "organic" },
        { domain: "google.sk", medium: "organic" },
        { domain: "google.de", medium: "organic" },
        { domain: "google.se", medium: "organic" },
        { domain: "bing.com", medium: "organic" },
        { domain: "search.seznam.cz", medium: "organic" },
        { domain: "search.yahoo.com", medium: "organic" },
        { domain: "duckduckgo.com", medium: "organic" },

        { domain: "facebook.com", medium: "social" },
        { domain: "instagram.com", medium: "social" },
        { domain: "linkedin.com", medium: "social" },
        { domain: "twitter.com", medium: "social" },
        { domain: "x.com", medium: "social" },
        { domain: "t.co", medium: "social" }
    ];

    for (var i = 0; i < rules.length; i++) {
        if (matchesDomain(rules[i].domain)) {
            return rules[i].medium;
        }
    }

    return "referral";
}

function () {
    var fallback = "not_available_GTM";
    var referrer = {{Referrer}};

    // Missing or unexpected input.
    if (typeof referrer !== "string") {
        return fallback;
    }

    referrer = referrer.trim();

    if (!referrer) {
        return fallback;
    }

    try {
        // No base URL: the referrer must be an absolute URL.
        var url = new URL(referrer);

        // Only accept ordinary web URLs.
        if (
            (url.protocol !== "https:" && url.protocol !== "http:") ||
            !url.hostname
        ) {
            return fallback;
        }

        // Keep the origin and path; discard query, fragment and credentials.
        return url.origin + url.pathname;
    } catch (error) {
        // Invalid URL or unavailable URL constructor.
        return fallback;
    }
}

function () {
    var medium = {{URL.query.utm_medium}};

    if (typeof medium === 'string' && medium.trim() && medium !== 'not_available_GTM') {
        return (medium.trim());
    }

    if ({{URL.query.gclid}}) {
        return 'cpc';
    }

    return ({{lookup.medium}});
}

